    "lead": "<h2>整回导读 · 读前想一想</h2><p>祭赛国，金光寺宝塔原供佛宝舍利，夜放祥光。不料碧波潭九头虫（九头驸马）偷走舍利，致使宝塔无光、寺僧蒙冤。悟空、八戒入潭探案，请来二郎神助阵，射伤九头虫、夺回舍利，宝塔重光。这一站讲\"冤案要查、宝物要还\"。</p><p>读这一站，看<b>\"查案+借将\"</b>：悟空既当侦探，也会\"借外援\"。</p><p class=\"q\">带着问题读：① 舍利为何被偷？② 为什么请二郎神？③ \"宝光\"象征什么？</p>",
